import heapq
from collections import defaultdict


def topo_order(deps: dict[str, list[str]]) -> list[str]:
    # Build the set of all tasks
    all_tasks = set(deps.keys())
    for prereqs in deps.values():
        for p in prereqs:
            all_tasks.add(p)

    # Build adjacency: prereq -> tasks that depend on it
    # and in-degree count for each task
    graph = defaultdict(list)
    in_degree = {task: 0 for task in all_tasks}

    for task, prereqs in deps.items():
        for p in prereqs:
            graph[p].append(task)
            in_degree[task] += 1

    # Initialize min-heap with all tasks that have in-degree 0
    heap = []
    for task in all_tasks:
        if in_degree[task] == 0:
            heapq.heappush(heap, task)

    result = []
    while heap:
        task = heapq.heappop(heap)
        result.append(task)
        for neighbor in graph[task]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(all_tasks):
        raise ValueError("Cycle detected in dependencies")

    return result
